sp_widget.client_script:
api.controller = function($scope, spUtil, $uibModal) {
  var c = this;

  // Track structural layout picker values safely
  c.customerObj = null;
  c.assetObj = null;

  c.form = { 
    description: '',
    customer: '',
    asset: ''
  };

  // Explicit capture callbacks to hold selection strings 
  c.onCustomerChange = function(val) {
    c.form.customer = val; 
  };

  c.onAssetChange = function(val) {
    c.form.asset = val;
  };

  c.openDetails = function(item) {
    c.selectedCase = item;
    c.modalInstance = $uibModal.open({
      templateUrl: 'caseDetailsModal',
      scope: $scope,
      size: 'lg'
    });
  };

  c.closeModal = function() {
    if (c.modalInstance) {
      c.modalInstance.close();
    }
  };

  c.submitForm = function() {
    var dynamicShortDesc = c.form.description ? c.form.description.substring(0, 40) + "..." : "New Support Case";

    c.server.get({
      action: 'createCase',
      short_description: dynamicShortDesc,
      description: c.form.description,
      customer: c.form.customer,
      asset: c.form.asset
    }).then(function(response) {
      // Re-populate dashboard case tracking list 
      $scope.data.cases = response.data.cases;

      // Clear fields text data safely
      c.form.description = '';
      c.form.customer = '';
      c.form.asset = '';

      // Clean UI input values without stripping Angular components out of context
      c.customerObj = null;
      c.assetObj = null;
    });
  };
};

sp_widget.script:
(function() {
    data.cases = [];
    var userId = gs.getUserID(); 

    if (!userId) { return; }

    // Process record insertion
    if (input && input.action === 'createCase') {
        var newCase = new GlideRecord('x_1558402_smart_0_support_case');
        newCase.initialize();

        newCase.setValue('short_description', input.short_description);
        newCase.setValue('description', input.description);
        newCase.setValue('customer', input.customer); // Make sure column name matches
        newCase.setValue('asset', input.asset);       // Make sure column name matches
        newCase.setValue('opened_by', userId); 

        newCase.insert();
    }

    // Fetch refreshed listings
    var gr = new GlideRecord('x_1558402_smart_0_support_case'); 
    gr.addQuery('opened_by', userId); 
    gr.orderByDesc('sys_created_on'); 
    gr.query();

    while (gr.next() && gr.canRead()) {
        data.cases.push({
            sys_id: gr.getUniqueValue(),
            number: gr.getDisplayValue('number'),
            short_description: gr.getDisplayValue('short_description'),
            description: gr.getDisplayValue('description'),
            customer: gr.getDisplayValue('u_customer'), 
            asset: gr.getDisplayValue('u_asset'),       
            state: gr.getDisplayValue('state'),
            opened: gr.getDisplayValue('sys_created_on')
        });
    }
})();
